-- Proyecto EcoAlerta El Alto.
-- 08_datos_catalogo.sql: tipos, características, estados y distritos.

-- Tipos de contaminación (el color y el ícono se usan en el mapa).
-- "Otro": el usuario explica de qué se trata en la descripción.
insert into public.tipo_contaminacion (id_tipo, nombre, color, icono) values
    (1, 'Residuos sólidos', '#1baf7a', 'delete'),
    (2, 'Quema de basura',  '#eb6834', 'local_fire_department'),
    (3, 'Aguas residuales', '#2a78d6', 'water_drop'),
    (4, 'Emisiones',        '#5f6b7a', 'factory'),
    (5, 'Escombros',        '#9c6b3e', 'construction'),
    (6, 'Malos olores',     '#8e44ad', 'air'),
    (7, 'Otro',             '#d4a017', 'help');

-- Características que el usuario marca al reportar.
-- Sin tipo (null): sirven para cualquier reporte. Con tipo: detalles de ese tipo.
-- Desde la app nadie agrega características; se cargan aquí.
insert into public.caracteristica (id_caracteristica, id_tipo, grupo, nombre) values
    -- Cerca de (lugares sensibles: ayudan a decidir la gravedad)
    ( 1, null, 'Cerca de', 'Escuela o colegio'),
    ( 2, null, 'Cerca de', 'Mercado o feria'),
    ( 3, null, 'Cerca de', 'Centro de salud'),
    ( 4, null, 'Cerca de', 'Río o canal'),
    ( 5, null, 'Cerca de', 'Viviendas'),
    ( 6, null, 'Cerca de', 'Parada de transporte'),
    ( 7, null, 'Cerca de', 'Plaza o área verde'),
    -- Efectos que notan los vecinos.
    (10, null, 'Efectos', 'Mal olor'),
    (11, null, 'Efectos', 'Humo'),
    (12, null, 'Efectos', 'Insectos o roedores'),
    (13, null, 'Efectos', 'Perros callejeros'),
    (14, null, 'Efectos', 'Bloquea el paso'),
    (15, null, 'Efectos', 'Agua estancada'),
    -- Residuos sólidos.
    (20, 1, 'Detalle', 'Basura doméstica'),
    (21, 1, 'Detalle', 'Plásticos'),
    (22, 1, 'Detalle', 'Restos orgánicos'),
    (23, 1, 'Detalle', 'Animales muertos'),
    (24, 1, 'Detalle', 'Residuos peligrosos (baterías, jeringas)'),
    -- Quema de basura.
    (30, 2, 'Detalle', 'Basura'),
    (31, 2, 'Detalle', 'Llantas'),
    (32, 2, 'Detalle', 'Cables'),
    (33, 2, 'Detalle', 'Pastizales'),
    (34, 2, 'Detalle', 'Humo negro'),
    -- Aguas residuales.
    (40, 3, 'Detalle', 'Alcantarilla rebalsada'),
    (41, 3, 'Detalle', 'Tubería rota'),
    (42, 3, 'Detalle', 'Descarga de industria'),
    (43, 3, 'Detalle', 'Llega a un río o canal'),
    -- Emisiones.
    (50, 4, 'Detalle', 'Ladrillera'),
    (51, 4, 'Detalle', 'Fábrica'),
    (52, 4, 'Detalle', 'Vehículos'),
    (53, 4, 'Detalle', 'Humo negro'),
    -- Escombros.
    (60, 5, 'Detalle', 'Restos de construcción'),
    (61, 5, 'Detalle', 'Tierra y piedras'),
    (62, 5, 'Detalle', 'En área verde'),
    -- Malos olores.
    (70, 6, 'Detalle', 'Olor a basura'),
    (71, 6, 'Detalle', 'Olor a desagüe'),
    (72, 6, 'Detalle', 'Olor químico');

-- Estados (Solucionado es el estado final)
insert into public.estado (id_estado, nombre, orden, es_final) values
    (1, 'Reportado',   1, false),
    (2, 'Confirmado',  2, false),
    (3, 'Prioritario', 3, false),
    (4, 'En atención', 4, false),
    (5, 'Solucionado', 5, true);

-- Distritos de El Alto (polígonos en GeoJSON, longitud/latitud)
-- Fuente: OpenStreetMap, octubre de 2026.
-- Borde exterior: límite del municipio de El Alto (así no entra La Paz).
-- Distritos 3, 8, 9 y 14: sus límites en OpenStreetMap.
-- Distritos 1, 2, 4, 5, 6, 7 y 12: OSM solo tiene el punto central de cada uno, así que el.
-- resto del municipio se repartió por cercanía a esos puntos (diagrama de Voronoi).
-- Distrito 13: zona rural del norte, con un punto central aproximado.
-- Distritos 10 y 11 no están en OpenStreetMap; su área quedó en los distritos vecinos.
-- OJO: son límites APROXIMADOS. Si se consiguen los oficiales, se reemplazan aquí.
insert into public.zona (nombre, distrito, geom)
