-- Perfiles de las cuentas que ya existían antes de crear la tabla usuario.
-- (el trigger solo crea perfiles para las cuentas nuevas)
insert into public.usuario (id_usuario, nombre_usuario, nombre_completo)
select id,
       left(coalesce(nullif(raw_user_meta_data ->> 'nombre_usuario', ''), split_part(email, '@', 1)), 30),
       coalesce(nullif(raw_user_meta_data ->> 'nombre_completo', ''), split_part(email, '@', 1))
  from auth.users
on conflict do nothing;

-- Cuentas creadas cuando Supabase pedía verificar el correo: las damos por verificadas.
-- (Además hay que desactivar "Confirm email" en Authentication -> Sign In / Providers -> Email)
update auth.users set email_confirmed_at = now() where email_confirmed_at is null;
